const cles = $input.all().map(i => i.json);

const SEUIL = 0.60;

const lignes = [];
const alertes = [];
let total = 0;

for (const k of cles) {
  const nom = k.key_alias || '(sans nom)';
  const depense = Number(k.spend || k.total_spend || 0);
  const plafond = Number(k.max_budget || 0);
  total += depense;
  const ratio = plafond > 0 ? depense / plafond : 0;
  lignes.push('| ' + nom + ' | ' + depense.toFixed(6) + ' $ | ' + (plafond > 0 ? plafond + ' $ (' + (ratio * 100).toFixed(1) + ' %)' : 'sans plafond') + ' |');
  if (plafond > 0 && ratio >= SEUIL) alertes.push(nom + ' a consomme ' + (ratio * 100).toFixed(1) + ' % de son plafond');
}

const rapport = [
  '## Depenses de jetons',
  '',
  '| Cle | Depense | Plafond |',
  '|---|---|---|',
  ...lignes,
  '',
  '**Total : ' + total.toFixed(6) + ' $** sur ' + cles.length + ' cle(s)',
  '',
  alertes.length ? '### Alerte\n' + alertes.map(a => '- ' + a).join('\n') : 'Aucun plafond proche d etre atteint.',
  '',
  'Horodatage : ' + new Date().toLocaleString('fr-FR'),
].join('\n');

return [{ json: { rapport, total: Number(total.toFixed(6)), alertes, nb_cles: cles.length } }];

const r = $input.first().json;
const lignes = [r.rapport, '', '---', '_Controle deterministe : aucune IA appelee, cout 0 jeton._'];
return [{ json: { ...r, rapport_complet: lignes.join('\n') } }];
